create table public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  email text not null unique
);
create function public.handle_new_user() returns trigger language plpgsql security definer set search_path = public as $$
begin insert into public.profiles(id, email) values (new.id, lower(new.email)); return new; end $$;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();

create table public.projects (
  id uuid primary key default gen_random_uuid(),
  name text not null check (char_length(name) between 1 and 100),
  owner_id uuid not null references public.profiles(id) on delete cascade,
  created_at timestamptz not null default now()
);
create index projects_owner_idx on public.projects(owner_id);

create table public.project_members (
  project_id uuid not null references public.projects(id) on delete cascade,
  user_id uuid not null references public.profiles(id) on delete cascade,
  primary key (project_id, user_id)
);
create index project_members_user_idx on public.project_members(user_id);

create table public.roles (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references public.projects(id) on delete cascade,
  name text not null check (char_length(name) between 1 and 50),
  assignee_id uuid,
  unique (id, project_id),
  foreign key (project_id, assignee_id) references public.project_members(project_id, user_id) on delete set null (assignee_id)
);
create index roles_project_idx on public.roles(project_id);

create table public.tasks (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references public.projects(id) on delete cascade,
  title text not null check (char_length(title) between 1 and 200),
  role_id uuid,
  status text not null default 'todo' check (status in ('todo', 'in_progress', 'done')),
  due_date date,
  created_at timestamptz not null default now(),
  foreign key (role_id, project_id) references public.roles(id, project_id) on delete set null (role_id)
);
create index tasks_project_idx on public.tasks(project_id);
create index tasks_role_idx on public.tasks(role_id);

create function public.is_member(p uuid) returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from project_members where project_id = p and user_id = auth.uid()) $$;
create function public.is_owner(p uuid) returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from projects where id = p and owner_id = auth.uid()) $$;

create function public.add_owner_membership() returns trigger language plpgsql security definer set search_path = public as $$
begin insert into project_members(project_id, user_id) values (new.id, new.owner_id); return new; end $$;
create trigger on_project_created after insert on public.projects for each row execute function public.add_owner_membership();

create function public.add_member(p uuid, member_email text) returns uuid language plpgsql security definer set search_path = public as $$
declare uid uuid;
begin
  if not is_owner(p) then raise exception 'only the project owner can add members' using errcode = '42501'; end if;
  select id into uid from profiles where email = lower(member_email);
  if uid is null then raise exception 'user not found' using errcode = 'P0002'; end if;
  insert into project_members(project_id, user_id) values (p, uid) on conflict do nothing;
  return uid;
end $$;
revoke execute on function public.add_member(uuid, text) from anon, public;
grant execute on function public.add_member(uuid, text) to authenticated;

-- Members may change status; only the owner may change plan fields (title, due date, role).
create function public.guard_task_update() returns trigger language plpgsql set search_path = public as $$
begin
  if not is_owner(old.project_id) and (new.title is distinct from old.title or new.due_date is distinct from old.due_date
     or new.role_id is distinct from old.role_id or new.project_id is distinct from old.project_id) then
    raise exception 'only the project owner can change plan fields' using errcode = '42501';
  end if;
  return new;
end $$;
create trigger tasks_guard before update on public.tasks for each row execute function public.guard_task_update();

alter table public.profiles enable row level security;
alter table public.projects enable row level security;
alter table public.project_members enable row level security;
alter table public.roles enable row level security;
alter table public.tasks enable row level security;

create policy profiles_select on public.profiles for select using (
  id = auth.uid() or exists (select 1 from project_members a join project_members b on a.project_id = b.project_id
                             where a.user_id = auth.uid() and b.user_id = profiles.id));
create policy projects_select on public.projects for select using (is_member(id));
create policy projects_insert on public.projects for insert with check (owner_id = auth.uid());
create policy projects_update on public.projects for update using (owner_id = auth.uid()) with check (owner_id = auth.uid());
create policy projects_delete on public.projects for delete using (owner_id = auth.uid());
create policy members_select on public.project_members for select using (is_member(project_id));
create policy roles_select on public.roles for select using (is_member(project_id));
create policy roles_insert on public.roles for insert with check (is_owner(project_id));
create policy roles_update on public.roles for update using (is_owner(project_id)) with check (is_owner(project_id));
create policy roles_delete on public.roles for delete using (is_owner(project_id));
create policy tasks_select on public.tasks for select using (is_member(project_id));
create policy tasks_insert on public.tasks for insert with check (is_owner(project_id));
create policy tasks_update on public.tasks for update using (is_member(project_id)) with check (is_member(project_id));
create policy tasks_delete on public.tasks for delete using (is_owner(project_id));
