import { DomainError } from "./errors";
import type { TaskPatch } from "./validate";

/** Rule: only the project creator may assign roles and change due dates (and other plan fields). */
export function isProjectOwner(ownerId: string, userId: string): boolean {
  return ownerId === userId;
}

export function assertOwner(ownerId: string, userId: string): void {
  if (!isProjectOwner(ownerId, userId)) {
    throw new DomainError("forbidden", "프로젝트 생성자만 역할과 마감일을 수정할 수 있습니다.");
  }
}

/** Status changes are open to members; anything else on a task is a plan change. */
export function assertCanPatchTask(patch: TaskPatch, ownerId: string, userId: string): void {
  if ("title" in patch || "due_date" in patch || "role_id" in patch) assertOwner(ownerId, userId);
}
