import type { PostgrestError } from "@supabase/supabase-js";
import { DomainError } from "../domain/errors";
import type { Member, ProjectSummary, Role, Task } from "../domain/types";
import type { TaskPatch } from "../domain/validate";
import type { Supabase } from "./supabase";

function must<T>(res: { data: T; error: PostgrestError | null }): T {
  const { data, error } = res;
  if (!error) return data;
  if (error.code === "42501") throw new DomainError("forbidden", "이 작업을 할 권한이 없습니다.");
  if (error.code === "P0002") throw new DomainError("not_found", "해당 이메일로 가입한 사용자가 없습니다.");
  if (error.code === "23503") throw new DomainError("invalid", "이 프로젝트에 속하지 않은 멤버나 역할입니다.");
  throw new Error(`DB error ${error.code}: ${error.message}`);
}

export async function listProjects(sb: Supabase): Promise<ProjectSummary[]> {
  return must(await sb.from("projects").select("id,name,owner_id").order("created_at", { ascending: false }));
}
export async function createProject(sb: Supabase, ownerId: string, name: string): Promise<ProjectSummary> {
  return must(await sb.from("projects").insert({ name, owner_id: ownerId }).select("id,name,owner_id").single());
}
export async function getProject(sb: Supabase, id: string): Promise<ProjectSummary> {
  const p = must(await sb.from("projects").select("id,name,owner_id").eq("id", id).maybeSingle());
  if (!p) throw new DomainError("not_found", "프로젝트를 찾을 수 없거나 접근 권한이 없습니다.");
  return p;
}
export async function getProjectParts(sb: Supabase, id: string) {
  const [m, r, t] = await Promise.all([
    sb.from("project_members").select("user_id, profiles(email)").eq("project_id", id),
    sb.from("roles").select("id,name,assignee_id").eq("project_id", id).order("name"),
    sb.from("tasks").select("id,title,status,due_date,role_id").eq("project_id", id).order("due_date", { nullsFirst: false }),
  ]);
  const members: Member[] = must(m).map((row) => {
    const p = row.profiles as unknown as { email: string } | null;
    return { user_id: row.user_id, email: p?.email ?? "(알 수 없음)" };
  });
  return { members, roles: must(r) as Role[], tasks: must(t) as Task[] };
}
export async function addMember(sb: Supabase, projectId: string, memberEmail: string): Promise<void> {
  must(await sb.rpc("add_member", { p: projectId, member_email: memberEmail }));
}
export async function createRole(sb: Supabase, projectId: string, name: string, assigneeId: string | null): Promise<Role> {
  return must(await sb.from("roles").insert({ project_id: projectId, name, assignee_id: assigneeId }).select("id,name,assignee_id").single());
}
export async function createTask(sb: Supabase, projectId: string, input: Omit<Task, "id" | "status">): Promise<Task> {
  return must(await sb.from("tasks").insert({ project_id: projectId, ...input }).select("id,title,status,due_date,role_id").single());
}
export async function getTaskProjectId(sb: Supabase, taskId: string): Promise<string> {
  const t = must(await sb.from("tasks").select("project_id").eq("id", taskId).maybeSingle());
  if (!t) throw new DomainError("not_found", "작업을 찾을 수 없거나 접근 권한이 없습니다.");
  return t.project_id;
}
export async function updateTask(sb: Supabase, taskId: string, patch: TaskPatch): Promise<Task> {
  return must(await sb.from("tasks").update(patch).eq("id", taskId).select("id,title,status,due_date,role_id").single());
}
